package fable.hideseek.imba.client;
import fable.hideseek.imba.ImbaExtension;import net.fabricmc.fabric.api.client.rendering.v1.WorldRenderEvents;import net.minecraft.client.MinecraftClient;import net.minecraft.registry.Registries;
public final class MaskHitboxEditorRenderer{private MaskHitboxEditorRenderer(){}public static void register(){WorldRenderEvents.AFTER_ENTITIES.register(ctx->{MinecraftClient client=MinecraftClient.getInstance();if(client.world==null||client.player==null||ctx.matrixStack()==null||ctx.consumers()==null)return;boolean editing=client.currentScreen instanceof MaskHitboxConfigScreen||client.player.getMainHandStack().isOf(ImbaExtension.MASK_HITBOX_TOOL)||client.player.getOffHandStack().isOf(ImbaExtension.MASK_HITBOX_TOOL);if(!editing)return;var camera=client.gameRenderer.getCamera().getPos();for(var player:client.world.getPlayers()){var block=ClientMaskData.BLOCKS.get(player.getUuid());if(block==null)continue;String id=Registries.BLOCK.getId(block).toString();var entry=MaskHitboxClientData.get(id);if(entry==null)continue;var box=entry.bounds().worldBox(player.getX(),player.getY(),player.getZ()).expand(0.002D);boolean selected=id.equals(MaskHitboxClientData.selectedId);WorldDebugBoxRenderer.drawWorldBox(ctx.matrixStack(),ctx.consumers(),camera,box,selected?80:255,selected?255:200,selected?120:40,255);}});}}
